// Prebaked datasets, generated by scripts/prebake.mjs (npm `prebuild`).
//
// These are loaded with dynamic import so Vite emits each one as its own chunk
// instead of inlining it into the entry bundle. They are the *floor*: the app
// paints from them immediately, then a live json.tarkov.dev fetch overwrites
// them in memory. See IMPLEMENTATION-PLAN.md Phase 4.
//
// A missing file is not an error — it means prebake has never run against a
// working network. Callers fall through to the live REST path.

const LOADERS = {
  maps: () => import('./maps.json'),
  tasks: () => import('./tasks.json'),
  keys: () => import('./keys.json'),
  bosses: () => import('./bosses.json'),
  spawns: () => import('./spawns.json'),
  intel: () => import('./intel.json'),
}

const cache = new Map()

// Resolves to { data, generatedAt, counts } or null. Never rejects.
export function loadPrebaked(name) {
  if (!cache.has(name)) {
    const loader = LOADERS[name]
    const promise = !loader
      ? Promise.resolve(null)
      : loader().then(module => {
          const payload = module?.default ?? module
          if (!payload?.data) return null
          return { data: payload.data, generatedAt: payload.generatedAt, counts: payload.counts }
        }).catch(error => {
          console.warn(`prebaked ${name} unavailable`, error)
          return null
        })
    cache.set(name, promise)
  }
  return cache.get(name)
}
